cd /tmp/claude-1000/-home-mike-nexus-code/6473a60e-9fa2-4bd9-9d0c-35324295cf68/scratchpad && node -e '
const d=JSON.parse(require("fs").readFileSync("mdev/api.json"));
const env=/^[A-Z][A-Z0-9_]{1,63}$/;const deny=/^AWS_|^GOOGLE_APPLICATION_CREDENTIALS$|_SSH|^GITHUB_TOKEN$/;
for(const p of Object.values(d)){
 if(!/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(p.id))console.log("pid",p.id);
 for(const e of p.env)if(!env.test(e))console.log("badenv",p.id,e);else if(deny.test(e))console.log("deny",p.id,e);
 if(p.api){const vars=[...p.api.matchAll(/\$\{([^}]*)\}/g)].map(x=>x[1]);const bad=vars.filter(v=>!p.env.includes(v));if(bad.length)console.log("tmplvar",p.id,p.api,bad);
  if(!/^https:\/\//.test(p.api)&&!/^\$\{/.test(p.api))console.log("scheme",p.id,p.api);
  if(/^\$\{|^https?:\/\/[^/]*\$\{/.test(p.api))console.log("hostenv",p.id,p.api);
  if(/@/.test(p.api.split("/").slice(0,3).join("/")))console.log("userinfo",p.id,p.api)}
 for(const m of Object.values(p.models)){if(/\.\.|^\/|\0/.test(m.id)||m.id.length>200)console.log("mid",p.id,m.id.slice(0,60))}
}
for(const id of ["openai","anthropic","google","mistral","groq","xai","deepseek","cohere","openrouter","together","togetherai","cerebras","fireworks-ai","fireworks","perplexity"])console.log(id,d[id]?d[id].api||"-":"MISSING")'

